    h,w=len(g),len(g[0]); seen=[[False]*w for _ in g]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and not seen[ny][nx]:
                                seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,cells))
    return out
def norm(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    my,mx=min(ys),min(xs)
    return frozenset((y-my,x-mx) for y,x in cells)
